use vstd::prelude::*;

verus! {

// Helper function to count true values in a sequence
spec fn count_true_spec(s: Seq<bool>) -> int
    decreases s.len()
{
    if s.len() == 0 {
        0
    } else {
        count_true_spec(s.drop_last()) + if s.last() { 1 } else { 0 }
    }
}

fn count_true(arr: &Vec<bool>) -> (count: u64)
    requires
        count_true_spec(arr@) <= u64::MAX,
    ensures
        count == count_true_spec(arr@),
{
    let mut count: u64 = 0;
    
    for idx in 0..arr.len()
        invariant
            idx <= arr.len(),
            count == count_true_spec(arr@.take(idx as int)),
            count_true_spec(arr@.take(idx as int)) <= u64::MAX,
    {
        if arr[idx] {
            count += 1;
        }
        // Here, count is always the number of true elements so far (for the prefix).
    }
    
    assert(arr@.take(arr.len() as int) == arr@);
    count
}

} // verus!